yakit.AutoInitYakit()
loglevel("info")

var count_200 = 0
var count_403 = 0
var count_302 = 0
yakit.StatusCard("状态码200",count_200)
yakit.StatusCard("状态码403",count_403)
yakit.StatusCard("状态码302",count_302)
var columns=["Method","状态码","请求路径","Body"]
yakit.EnableTable("GET执行结果返回",columns)
outputGet = func(Method, statuscode,path,body) {
    data = make(map[string]var)
    data["Method"] = Method
    data["状态码"] = statuscode
    data["请求路径"] = path
    data["Body"] = body
    yakit.TableData("GET执行结果返回", data)
}
yakit.EnableTable("POST执行结果返回",columns)
outputPost = func(Method, statuscode,path,body) {
    data = make(map[string]var)
    data["Method"] = Method
    data["状态码"] = statuscode
    data["请求路径"] = path
    data["Body"] = body
    yakit.TableData("POST执行结果返回", data)
}

GetSend = func(URL,path){
    yakit.Info("URL: %v,Path: %v" %[URL,path])
    var reponse
    var statusCode
    var body
    rsp,err =http.Get(URL,http.fakeua())
    if(rsp!=nil){
        statusCode = rsp.StatusCode
        if(statusCode==200){
            count_200++
            yakit.StatusCard("状态码200",count_200)
        }elif(statusCode==403){
            count_403++
            yakit.StatusCard("状态码403",count_403)
        }elif(statusCode==302){
            count_302++
            yakit.StatusCard("状态码302",count_302)
        }
        body = rsp.Data()
        outputGet("GET",statusCode,path,body)

    }

}
PostSend = func(Host,Path){
    var statusCode
    var body
    var reponse
    packet = f`POST ${Path} HTTP/1.1
Host: ${Host}
Accept: */*
Accept-Encoding: gzip, deflate
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
Content-Type:application/x-www-form-urlencoded
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/102.0.0.0 Safari/537.36`
    rsp, req, err = poc.HTTP(packet, poc.redirectTimes(0))
    if rsp != nil {
        httpRsp,err = poc.ParseBytesToHTTPResponse(rsp)
        if err!=nil{
            die(err)
        }
       statusCode = httpRsp.Status
       if(str.Contains(statusCode,"200")){
            count_200++
            yakit.StatusCard("状态码200",count_200)
        }elif(str.Contains(statusCode,"403")){
            count_403++
            yakit.StatusCard("状态码403",count_403)
        }elif(str.Contains(statusCode,"403")){
            count_403++
            yakit.StatusCard("状态码403",count_403)
        }
       header,body = poc.Split(rsp)
       str_body= str.ParseStringToHosts(body)
       outputPost("POST",statusCode,Path,str_body)
    }
}
wg := sync.NewSizedWaitGroup(5)
def submitTask(host_List,path,URL,replay_URL,SetPost){ 
    var reponse_List 
    if(path.StartsWith("图像文件")){
        path = ""
    }elif(replay_URL!=nil){
        URL = replay_URL
    }elif(path.StartsWith("https://") || path.StartsWith("http://")){
        URL = path
    }elif(URL.StartsWith("http://")){
        URL = ("http://%v%v" %[host_List,path])
    }else{
        URL = ("https://%v%v" %[host_List,path])
    }
     wg.Add()    
     go fn{ 
         defer wg.Done()        
         GetSend(URL,path)
         if(SetPost){
            PostSend(host_List,path)
         }
     }
}
Re = func(host,path1,isTls){//正则处理Path并返回
    var List = []
    regex=`(?:"|')((?:(?:[a-zA-Z]{1,10}://|//)[^"'/]{1,}\.[a-zA-Z]{2,}[^"']{0,})|(?:/|\.\./|\./)[^"'><,;| *()(%%$^/\\\[\]][^"'><,;|()]{1,})|([a-zA-Z0-9_\-/]{1,}/[a-zA-Z0-9_\-/]{1,}\.(?:[a-zA-Z]{1,4}|action)(?:[\?|#][^"|']{0,}|))|([a-zA-Z0-9_\-/]{1,}/[a-zA-Z0-9_\-/]{3,}(?:[\?|#][^"|']{0,}|))|([a-zA-Z0-9_\-]{1,}\.(?:php|asp|aspx|jsp|json|action|html|js|txt|xml)(?:[\?|#][^"|']{0,}|))(?:"|')`
    regex1 = `\.(jpg|jpeg|png|gif|bmp|PNG|JPG|JPEG|GIF|Jpg|Png|Jpeg|vue)$`
    packet = f`GET /${path1} HTTP/1.1
Host: ${host}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:101.0) Gecko/20100101 Firefox/101.0
`
    rsp,req,_ = poc.HTTP(packet, 
    poc.https(isTls),
    poc.redirectTimes(0),
    )
    hand, body = str.SplitHTTPHeadersAndBodyFromPacket(rsp)
    result = re.FindAll(body,regex)//正则获取接口
    for Path in result{
        Path = str.ReplaceAll(Path,"'",'')//二次匹配
        Path = str.ReplaceAll(Path,"\"",'')
        if(str.StartsWith(Path,"./")){
            Path = str.ReplaceAll(Path,"./",'')
        }
        if(str.StartsWith(Path,"../")){
            Path = str.ReplaceAll(Path,"../",'')
        }
        if(str.StartsWith(Path,"https://")||str.StartsWith(Path,"http://")){
            Path = Path
        }elif(!str.StartsWith(Path,"/")){
            Path="/"+Path
        }else{
            Path = Path
        }
        result1 = re.FindAll(Path,regex1)
        for i in result1{
            Path = "图像文件"
        }
        List.Append(Path)
    }
    return List
}
